@test "container cleanup after job cancellation" {
    run_srun --container-image=ubuntu:24.04 bash -c 'echo ${SLURM_JOB_ID} ; echo ${SLURM_STEP_ID}'
    job_id="${lines[2]}"
    step_id="${lines[3]}"

    run_srun --container-image=ubuntu:24.04 sleep 30s &
    job_pid=$!

    sleep 2s
    scancel "${job_id}.$((step_id + 1))"
